#[rustfmt::skip]
pub fn holds(i: usize, v: &[Val<'_>], t: &Target) -> bool {
    match i {
        0 => !(cmp(Cmp::Eq, v[0], Val::Bool(true)) && cmp(Cmp::Eq, v[1], Val::Bool(true))),
        1 => !(cmp(Cmp::Eq, v[2], Val::Bool(true)) && (cmp(Cmp::Eq, v[0], Val::Bool(true)) || cmp(Cmp::Eq, v[1], Val::Bool(true)))),
        2 => !(TargetAtom::Model("kimi_k3").eval(t) && cmp(Cmp::Gt, v[5], Val::Nat(16)) && cmp(Cmp::Eq, v[6], Val::Unset)) || cmp(Cmp::Eq, v[7], Val::Bool(true)),
        3 => !(cmp(Cmp::Eq, v[12], Val::Bool(true)) && cmp(Cmp::Eq, v[25], Val::Bool(true))),
        4 => !cmp(Cmp::Eq, v[13], Val::Bool(true)) || (cmp(Cmp::Eq, v[14], Val::Bool(true)) && cmp(Cmp::Eq, v[9], Val::Bool(true)) && !TargetAtom::Cap("indexer_pooled").eval(t)),
        5 => !cmp(Cmp::Eq, v[22], Val::Bool(true)) || (!cmp(Cmp::Eq, v[8], Val::Bool(true)) && !cmp(Cmp::Eq, v[9], Val::Bool(true))),
        6 => !cmp(Cmp::Eq, v[25], Val::Bool(true)) || (!cmp(Cmp::Gt, v[23], Val::Nat(1)) && !cmp(Cmp::Eq, v[24], Val::Bool(true))),
        7 => !cmp(Cmp::Eq, v[26], Val::Bool(true)) || cmp(Cmp::Eq, v[25], Val::Bool(true)),
        8 => !cmp(Cmp::Ne, v[29], Val::Unset) || (TargetAtom::Arch("metal3").eval(t) && TargetAtom::Tp(1).eval(t) && (TargetAtom::Model("llama").eval(t) || TargetAtom::Model("qwen3").eval(t))),
        9 => !cmp(Cmp::Ne, v[29], Val::Unset) || (cmp(Cmp::Eq, v[28], Val::Unset) && !cmp(Cmp::Eq, v[0], Val::Bool(true)) && !cmp(Cmp::Eq, v[4], Val::Bool(true)) && cmp(Cmp::Eq, v[30], Val::Unset)),
        10 => !cmp(Cmp::Ne, v[34], Val::Unset) || (cmp(Cmp::Ne, v[33], Val::Unset) || TargetAtom::Cap("bundled_segment_pair").eval(t)),
        11 => !cmp(Cmp::Eq, v[32], Val::Str("1")) || cmp(Cmp::Eq, v[35], Val::Bool(true)),
        12 => !cmp(Cmp::Eq, v[31], Val::Str("1")) || cmp(Cmp::Eq, v[35], Val::Bool(true)),
        13 => !cmp(Cmp::Eq, v[37], Val::Bool(true)) || (!cmp(Cmp::Eq, v[36], Val::Bool(true)) && cmp(Cmp::Eq, v[28], Val::Unset)),
        _ => true,
    }
}

/// The first `Check::Load` constraint `v` (indexed like [`KNOBS`]) violates on `t`.
pub fn violation(v: &[Val<'_>], t: &Target) -> Option<usize> {
    (0..CONSTRAINTS.len()).find(|&i| CONSTRAINTS[i].check == Check::Load && !holds(i, v, t))
}
